<?php require '../../../config/bootstrap.php';$u=require_auth();require_role($u,['owner','admin','manager','operator']);require_csrf();$d=request_json();$device=(int)($d['device_id']??0);$type=(string)($d['command_type']??'');$allowed=['dispense_feed','fan_on','fan_off','lamp_on','lamp_off'];if(!$device||!in_array($type,$allowed,true))json_response(['error'=>'Comando inválido'],422);$s=db()->prepare('SELECT id FROM devices WHERE id=? AND tenant_id=? AND status="active"');$s->execute([$device,$u['tenant_id']]);if(!$s->fetch())json_response(['error'=>'Dispositivo inválido'],404);$payload=$d['payload']??[];if($type==='dispense_feed'){ $kg=(float)($payload['kg']??0);if($kg<=0||$kg>5)json_response(['error'=>'Dose deve estar entre 0 e 5 kg'],422);$payload=['kg'=>$kg];}$expires=date('Y-m-d H:i:s',time()+120);$idem=bin2hex(random_bytes(12));$s=db()->prepare('INSERT INTO device_commands(tenant_id,device_id,created_by,command_type,payload,idempotency_key,expires_at) VALUES(?,?,?,?,?,?,?)');$s->execute([$u['tenant_id'],$device,$u['id'],$type,json_encode($payload),$idem,$expires]);$id=(int)db()->lastInsertId();audit($u,'create','device_command',$id,['device_id'=>$device,'type'=>$type]);json_response(['id'=>$id,'expires_at'=>$expires],201);
